// Page skeleton: list the embedded sample images and draw the chosen one on the canvas.
// Runs entirely in the browser: no server. Sample images come from static/samples.js
// (generated by tools/embed_samples.py). A canvas is used, not an <img>, because the
// next step paints the editable mask on top of it and later steps read its pixels.

const select = document.getElementById("sample");
const canvas = document.getElementById("imageCanvas");
const ctx = canvas.getContext("2d");
const loadMsg = document.getElementById("loadMsg");
const imgInfo = document.getElementById("imgInfo");

const samples = Array.isArray(window.SAMPLES) ? window.SAMPLES : [];

function showImage(sample) {
  const img = new Image();
  img.onload = () => {
    canvas.width = img.naturalWidth;
    canvas.height = img.naturalHeight;
    ctx.drawImage(img, 0, 0);
    imgInfo.textContent = `${img.naturalWidth} x ${img.naturalHeight} px`;
    loadMsg.textContent = "";
  };
  img.onerror = () => { loadMsg.textContent = `Could not load ${sample.name}.`; };
  img.src = sample.src;
}

if (samples.length === 0) {
  loadMsg.textContent = "No sample images found. Run: python tools/embed_samples.py";
} else {
  samples.forEach((s, i) => {
    const opt = document.createElement("option");
    opt.value = String(i);
    opt.textContent = s.name;
    select.appendChild(opt);
  });
  select.addEventListener("change", () => showImage(samples[Number(select.value)]));
  showImage(samples[0]);
}
